  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ServiceType {
  MEDICAL = 'Serviços Médicos',
  MAINTENANCE = 'Manutenção (Corretiva/Preventiva)',
  DAILY = 'Diária',
  BIDDING = 'Licitação/Contrato',
  MATERIALS = 'Materiais'
}

export interface Person {
  id: string;
  name: string;
  role: string;
}

export interface Task {
  id: string;
  personId: string;
  type: ServiceType;
  description: string;
  date: string; // ISO date string YYYY-MM-DD
  duration: number; // minutes or hours, let's use hours
}

export interface AppState {
  people: Person[];
  tasks: Task[];
}

