import { GoogleGenAI } from "@google/genai";
import { Task, Person } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getProductivityInsights(tasks: Task[], people: Person[]) {
  if (tasks.length === 0) return "Ainda não há dados suficientes para uma análise.";

  const prompt = `
    Analise os seguintes dados de produtividade de uma equipe:

    Equipe: ${people.map(p => p.name).join(', ')}

    Tarefas Registradas:
    ${tasks.map(t => `- ${t.date}: ${people.find(p => p.id === t.personId)?.name} realizou ${t.type} (${t.description}) por ${t.duration} horas.`).join('\n')}

    Por favor, forneça um resumo executivo da produtividade, identifique possíveis gargalos e sugira melhorias. 
    Responda em Português do Brasil de forma profissional e motivadora.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Erro ao obter insights da IA:", error);
    return "Desculpe, não foi possível gerar insights no momento.";
  }
}

import React, { useState, useEffect } from 'react';
import { Person, Task, AppState } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
import DailyLog from './components/DailyLog';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs'>('dashboard');
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('prod360_data');
    return saved ? JSON.parse(saved) : { people: [], tasks: [] };
  });

  useEffect(() => {
    localStorage.setItem('prod360_data', JSON.stringify(state));
  }, [state]);

  const addPerson = (person: Person) => {
    setState(prev => ({ ...prev, people: [...prev.people, person] }));
  };

  const removePerson = (id: string) => {
    setState(prev => ({
      ...prev,
      people: prev.people.filter(p => p.id !== id),
      tasks: prev.tasks.filter(t => t.personId !== id)
    }));
  };

  const addTask = (task: Task) => {
    setState(prev => ({ ...prev, tasks: [...prev.tasks, task] }));
  };

  const removeTask = (id: string) => {
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.filter(t => t.id !== id)
    }));
  };

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8">
          <h1 className="text-3xl font-bold text-slate-800">
            {activeTab === 'dashboard' && 'Visão Geral'}
            {activeTab === 'people' && 'Gerenciar Equipe'}
            {activeTab === 'logs' && 'Registro Diário'}
          </h1>
          <p className="text-slate-500 mt-2">
            {activeTab === 'dashboard' && 'Monitore a produtividade e o desempenho da equipe.'}
            {activeTab === 'people' && 'Adicione ou remova membros da sua equipe.'}
            {activeTab === 'logs' && 'Visualize e gerencie os serviços realizados diariamente.'}
          </p>
        </header>

        {activeTab === 'dashboard' && (
          <Dashboard state={state} />
        )}

        {activeTab === 'people' && (
          <PeopleManager people={state.people} onAdd={addPerson} onRemove={removePerson} />
        )}

        {activeTab === 'logs' && (
          <DailyLog 
            tasks={state.tasks} 
            people={state.people} 
            onAddTask={addTask} 
            onRemoveTask={removeTask} 
          />
        )}
      </main>
    </div>
  );
};

export default App;

