import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';
import { AppState, ServiceType } from '../types';
import { SERVICE_COLORS, Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Group tasks by service type for Pie Chart
  const typeData = useMemo(() => {
    const counts: Record<string, number> = {};
    Object.values(ServiceType).forEach(val => counts[val] = 0);
    state.tasks.forEach(t => {
      counts[t.type] += t.duration;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [state.tasks]);

  // Group tasks by date for Bar Chart (Last 7 days)
  const barData = useMemo(() => {
    const dates: Record<string, Record<string, number>> = {};
    // Get last 7 days including today
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    last7Days.forEach(date => {
      dates[date] = { date };
      Object.values(ServiceType).forEach(type => {
        dates[date][type] = 0;
      });
    });

    state.tasks.forEach(t => {
      if (dates[t.date]) {
        dates[t.date][t.type] += t.duration;
      }
    });

    return Object.values(dates);
  }, [state.tasks]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    const result = await getProductivityInsights(state.tasks, state.people);
    setAiInsight(result);
    setLoadingAi(false);
  };

  const totalHours = state.tasks.reduce((acc, t) => acc + t.duration, 0);

  return (
    <div className="space-y-8">
      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Total de Horas Registradas</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{totalHours}h</p>
          <div className="mt-4 flex items-center text-emerald-600 text-sm font-medium">
            <Icons.Plus />
            <span>Métricas em tempo real</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Colaboradores Ativos</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{state.people.length}</p>
          <div className="mt-4 flex items-center text-blue-600 text-sm font-medium">
            <Icons.People />
            <span className="ml-1">Equipe monitorada</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Tarefas Registradas</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{state.tasks.length}</p>
          <div className="mt-4 flex items-center text-violet-600 text-sm font-medium">
            <Icons.Task />
            <span className="ml-1">Registros totais</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Productivity Over Time */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Produtividade por Tipo (Últimos 7 dias)</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="date" 
                  tickFormatter={(val) => val.split('-').slice(1).reverse().join('/')}
                  stroke="#94a3b8"
                  fontSize={12}
                />
                <YAxis stroke="#94a3b8" fontSize={12} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Legend iconType="circle" />
                {Object.entries(SERVICE_COLORS).map(([type, color]) => (
                  <Bar key={type} dataKey={type} fill={color} radius={[4, 4, 0, 0]} stackId="a" />
                ))}
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Distribution Pie */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Distribuição de Esforço</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={SERVICE_COLORS[entry.name as ServiceType] || '#ccc'} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" align="center" layout="horizontal" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* AI Insights Section */}
      <div className="bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl p-8 text-white shadow-xl">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-2">
              <Icons.Sparkles />
              <h2 className="text-xl font-bold">Insights de IA (Gemini)</h2>
            </div>
            <p className="text-indigo-100 mb-6">Receba uma análise detalhada da produtividade da sua equipe baseada nos dados registrados.</p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights}
                className="bg-white text-indigo-600 px-6 py-3 rounded-xl font-bold hover:bg-indigo-50 transition-colors shadow-lg"
              >
                Gerar Relatório de IA
              </button>
            )}
          </div>

          {loadingAi && (
            <div className="flex items-center gap-3">
              <div className="animate-spin h-6 w-6 border-4 border-white border-t-transparent rounded-full"></div>
              <span className="font-medium">Analisando dados...</span>
            </div>
          )}

          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/10 backdrop-blur-md rounded-xl p-6 border border-white/20">
              <div className="flex justify-between items-start mb-4">
                <span className="text-xs font-bold uppercase tracking-wider bg-white/20 px-2 py-1 rounded">Relatório Atual</span>
                <button 
                  onClick={() => setAiInsight(null)}
                  className="text-white/60 hover:text-white"
                >
                  <Icons.Trash />
                </button>
              </div>
              <div className="text-sm leading-relaxed whitespace-pre-wrap">
                {aiInsight}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Person } from '../types';
import { Icons } from '../constants';

interface PeopleManagerProps {
  people: Person[];
  onAdd: (person: Person) => void;
  onRemove: (id: string) => void;
}

const PeopleManager: React.FC<PeopleManagerProps> = ({ people, onAdd, onRemove }) => {
  const [name, setName] = useState('');
  const [role, setRole] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !role.trim()) return;

    onAdd({
      id: Math.random().toString(36).substr(2, 9),
      name,
      role
    });
    setName('');
    setRole('');
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
      {/* Form Card */}
      <div className="md:col-span-1">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 sticky top-6">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Cadastrar Colaborador</h3>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Nome Completo</label>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ex: João Silva"
                className="w-full px-4 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Cargo / Função</label>
              <input
                type="text"
                value={role}
                onChange={(e) => setRole(e.target.value)}
                placeholder="Ex: Enfermeiro, Técnico..."
                className="w-full px-4 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg flex items-center justify-center gap-2"
            >
              <Icons.Plus />
              Adicionar
            </button>
          </form>
        </div>
      </div>

      {/* List Card */}
      <div className="md:col-span-2">
        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center">
            <h3 className="text-lg font-bold text-slate-800">Membros da Equipe</h3>
            <span className="bg-slate-100 text-slate-600 px-3 py-1 rounded-full text-xs font-bold">
              {people.length} Total
            </span>
          </div>

          <div className="divide-y divide-slate-100">
            {people.length === 0 ? (
              <div className="p-10 text-center text-slate-400">
                <div className="bg-slate-50 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Icons.People />
                </div>
                <p>Nenhum colaborador cadastrado ainda.</p>
              </div>
            ) : (
              people.map((person) => (
                <div key={person.id} className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">
                      {person.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <p className="font-bold text-slate-800">{person.name}</p>
                      <p className="text-sm text-slate-500">{person.role}</p>
                    </div>
                  </div>
                  <button
                    onClick={() => onRemove(person.id)}
                    className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                    title="Remover colaborador"
                  >
                    <Icons.Trash />
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PeopleManager;

import React, { useState, useMemo } from 'react';
import { Person, Task, ServiceType } from '../types';
import { Icons, SERVICE_COLORS } from '../constants';

interface DailyLogProps {
  tasks: Task[];
  people: Person[];
  onAddTask: (task: Task) => void;
  onRemoveTask: (id: string) => void;
}

const DailyLog: React.FC<DailyLogProps> = ({ tasks, people, onAddTask, onRemoveTask }) => {
  const [selectedPerson, setSelectedPerson] = useState('');
  const [selectedType, setSelectedType] = useState<ServiceType>(ServiceType.MEDICAL);
  const [description, setDescription] = useState('');
  const [hours, setHours] = useState<number>(1);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Filter state
  const [filterDate, setFilterDate] = useState(new Date().toISOString().split('T')[0]);

  const filteredTasks = useMemo(() => {
    return tasks
      .filter(t => t.date === filterDate)
      .sort((a, b) => b.id.localeCompare(a.id));
  }, [tasks, filterDate]);

  const handleAddTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPerson || !description.trim()) return;

    onAddTask({
      id: Math.random().toString(36).substr(2, 9),
      personId: selectedPerson,
      type: selectedType,
      description,
      date,
      duration: hours
    });

    setDescription('');
    setHours(1);
  };

  return (
    <div className="space-y-8">
      {/* Task Input Section */}
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-bold text-slate-800 mb-6">Novo Registro de Serviço</h3>
        <form onSubmit={handleAddTask} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4 items-end">
          <div className="lg:col-span-1">
