import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell
} from 'recharts';
import { AppState, ServiceType } from '../types';
import { SERVICE_COLORS, Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Group tasks by service type for Pie Chart
  const typeData = useMemo(() => {
    const counts: Record<string, number> = {};
    Object.values(ServiceType).forEach(val => counts[val] = 0);
    state.tasks.forEach(t => {
      counts[t.type] += t.duration;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [state.tasks]);

  // Group tasks by date for Bar Chart (Last 7 days)
  const barData = useMemo(() => {
    // Fix: Using any for the record to allow the 'date' string key alongside numeric service types
    const dates: Record<string, any> = {};
    // Get last 7 days including today
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    last7Days.forEach(date => {
      dates[date] = { date };
      Object.values(ServiceType).forEach(type => {
        dates[date][type] = 0;
      });
    });

    state.tasks.forEach(t => {
      if (dates[t.date]) {
        dates[t.date][t.type] += t.duration;
      }
    });

    return Object.values(dates);
  }, [state.tasks]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    const result = await getProductivityInsights(state.tasks, state.people);
    // Ensure we handle potentially undefined text from Gemini response
    setAiInsight(result || "Não foi possível gerar insights no momento.");
    setLoadingAi(false);
  };

  const totalHours = state.tasks.reduce((acc, t) => acc + t.duration, 0);

  return (
    <div className="space-y-8">
      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Total de Horas Registradas</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{totalHours}h</p>
          <div className="mt-4 flex items-center text-emerald-600 text-sm font-medium">
            <Icons.Plus />
            <span>Métricas em tempo real</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Colaboradores Ativos</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{state.people.length}</p>
          <div className="mt-4 flex items-center text-blue-600 text-sm font-medium">
            <Icons.People />
            <span className="ml-1">Equipe monitorada</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Tarefas Registradas</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{state.tasks.length}</p>
          <div className="mt-4 flex items-center text-violet-600 text-sm font-medium">
            <Icons.Task />
            <span className="ml-1">Registros totais</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Productivity Over Time */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Produtividade por Tipo (Últimos 7 dias)</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={barData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="date" 
                  tickFormatter={(val) => val.split('-').slice(1).reverse().join('/')}
                  stroke="#94a3b8"
                  fontSize={12}
                />
                <YAxis stroke="#94a3b8" fontSize={12} />
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Legend iconType="circle" />
                {Object.entries(SERVICE_COLORS).map(([type, color]) => (
                  <Bar key={type} dataKey={type} fill={color} radius={[4, 4, 0, 0]} stackId="a" />
                ))}
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Distribution Pie */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Distribuição de Esforço</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={SERVICE_COLORS[entry.name as ServiceType] || '#ccc'} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" align="center" layout="horizontal" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* AI Insights Section */}
      <div className="bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl p-8 text-white shadow-xl">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="flex-1">
            <div className="flex items-center gap-2 mb-2">
              <Icons.Sparkles />
              <h2 className="text-xl font-bold">Insights de IA (Gemini)</h2>
            </div>
            <p className="text-indigo-100 mb-6">Receba uma análise detalhada da produtividade da sua equipe baseada nos dados registrados.</p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights}
                className="bg-white text-indigo-600 px-6 py-3 rounded-xl font-bold hover:bg-indigo-50 transition-colors shadow-lg"
              >
                Gerar Relatório de IA
              </button>
            )}
          </div>

          {loadingAi && (
            <div className="flex items-center gap-3">
              <div className="animate-spin h-6 w-6 border-4 border-white border-t-transparent rounded-full"></div>
              <span className="font-medium">Analisando dados...</span>
            </div>
          )}

          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/10 backdrop-blur-md rounded-xl p-6 border border-white/20">
              <div className="flex justify-between items-start mb-4">
                <span className="text-xs font-bold uppercase tracking-wider bg-white/20 px-2 py-1 rounded">Relatório Atual</span>
                <button 
                  onClick={() => setAiInsight(null)}
                  className="text-white/60 hover:text-white"
                >
                  <Icons.Trash />
                </button>
              </div>
              <div className="text-sm leading-relaxed whitespace-pre-wrap">
                {aiInsight}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

export enum ServiceType {
  MEDICAL = 'Serviços Médicos',
  MAINTENANCE = 'Manutenção (Corretiva/Preventiva)',
