import { GoogleGenAI } from "@google/genai";
import { Task, Person } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getProductivityInsights(tasks: Task[], people: Person[]) {
  if (tasks.length === 0) return "Ainda não há dados suficientes para uma análise.";

  const prompt = `
    Analise os seguintes dados de produção quantitativa de uma equipe:

    Equipe: ${people.map(p => p.name).join(', ')}

    Registros de Produção:
    ${tasks.map(t => `- ${t.date}: ${people.find(p => p.id === t.personId)?.name} realizou ${t.type} (${t.description}) - Quantidade: ${t.quantity}.`).join('\n')}

    Por favor, forneça um resumo executivo baseado nos volumes produzidos, identifique quem são os destaques em termos de volume e sugira melhorias nos processos. 
    Considere que o foco é o "quantitativo realizado".
    Responda em Português do Brasil de forma profissional e motivadora.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Erro ao obter insights da IA:", error);
    return "Desculpe, não foi possível gerar insights no momento.";
  }
}

