import React, { useState, useMemo } from 'react';
import { Person, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';

interface DailyLogProps {
  tasks: Task[];
  people: Person[];
  categories: ServiceCategory[];
  onAddTask: (task: Task) => void;
  onRemoveTask: (id: string) => void;
}

const DailyLog: React.FC<DailyLogProps> = ({ tasks, people, categories, onAddTask, onRemoveTask }) => {
  const [selectedPerson, setSelectedPerson] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState('');
  const [description, setDescription] = useState('');
  const [quantity, setQuantity] = useState<number>(1);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [filterDate, setFilterDate] = useState(new Date().toISOString().split('T')[0]);

  // Set first category as default if available
  useState(() => {
    if (categories.length > 0 && !selectedCategoryId) {
      setSelectedCategoryId(categories[0].id);
    }
  });

  const filteredTasks = useMemo(() => {
    return tasks
      .filter(t => t.date === filterDate)
      .sort((a, b) => b.id.localeCompare(a.id));
  }, [tasks, filterDate]);

  const handleAddTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPerson || !selectedCategoryId || !description.trim()) return;

    onAddTask({
      id: Math.random().toString(36).substr(2, 9),
      personId: selectedPerson,
      serviceCategoryId: selectedCategoryId,
      description: description.trim(),
      date,
      quantity: quantity
    });

    setDescription('');
