                >
                  <Icons.Trash />
                </button>
              </div>
              <div className="text-sm leading-relaxed whitespace-pre-wrap">
                {aiInsight}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import { GoogleGenAI } from "@google/genai";
import { Task, Person, ServiceCategory } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getProductivityInsights(tasks: Task[], people: Person[], categories: ServiceCategory[]) {
  if (tasks.length === 0) return "Ainda não há dados suficientes para uma análise.";

  const prompt = `
    Analise os seguintes dados de produção quantitativa de uma equipe:

    Categorias de Serviço Monitoradas: ${categories.map(c => c.name).join(', ')}
    Equipe: ${people.map(p => p.name).join(', ')}

    Registros de Produção:
    ${tasks.map(t => {
      const p = people.find(person => person.id === t.personId);
      const c = categories.find(cat => cat.id === t.serviceCategoryId);
      return `- ${t.date}: ${p?.name} realizou ${c?.name} (${t.description}) - Quantidade: ${t.quantity}.`;
    }).join('\n')}

    Por favor, forneça um resumo executivo baseado nos volumes produzidos, identifique quais categorias estão com maior volume e sugira melhorias. 
    Responda em Português do Brasil de forma profissional e motivadora.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Erro ao obter insights da IA:", error);
    return "Desculpe, não foi possível gerar insights no momento.";
  }
}

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line, AreaChart, Area
} from 'recharts';
import { AppState, Task } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

type TimeRange = 'daily' | 'weekly' | 'fortnightly' | 'monthly' | 'quarterly' | 'semiannual' | 'annual';

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const [timeRange, setTimeRange] = useState<TimeRange>('weekly');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Filter tasks based on selected range
  const filteredTasks = useMemo(() => {
    const now = new Date();
    const rangeInDays: Record<TimeRange, number> = {
      daily: 1,
      weekly: 7,
      fortnightly: 15,
      monthly: 30,
      quarterly: 90,
      semiannual: 180,
      annual: 365
    };

    const thresholdDate = new Date();
    thresholdDate.setDate(now.getDate() - rangeInDays[timeRange]);
    const thresholdStr = thresholdDate.toISOString().split('T')[0];

    return state.tasks.filter(t => t.date >= thresholdStr);
  }, [state.tasks, timeRange]);

  // Data for Evolution Line Chart
  const evolutionData = useMemo(() => {
    const dates: Record<string, any> = {};
    const daysToGenerate: Record<TimeRange, number> = {
      daily: 1, weekly: 7, fortnightly: 15, monthly: 30, quarterly: 90, semiannual: 180, annual: 365
    };

    const count = daysToGenerate[timeRange];
    for (let i = 0; i < count; i++) {
      const d = new Date();
      d.setDate(d.getDate() - (count - 1 - i));
      const dateStr = d.toISOString().split('T')[0];
      dates[dateStr] = { date: dateStr, total: 0 };
      state.serviceCategories.forEach(cat => {
        dates[dateStr][cat.name] = 0;
      });
    }

    filteredTasks.forEach(t => {
      if (dates[t.date]) {
        const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
        if (cat) {
          dates[t.date][cat.name] += t.quantity;
          dates[t.date].total += t.quantity;
        }
      }
    });

    return Object.values(dates);
  }, [filteredTasks, state.serviceCategories, timeRange]);

  // Data for Individual Productivity (Bar Chart)
  const teamData = useMemo(() => {
    const data = state.people.map(person => {
      const total = filteredTasks
        .filter(t => t.personId === person.id)
        .reduce((sum, t) => sum + t.quantity, 0);
      return {
        name: person.name,
        quantity: total
      };
    });
    return data.sort((a, b) => b.quantity - a.quantity);
  }, [filteredTasks, state.people]);

  // Data for Category Distribution (Pie Chart)
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.serviceCategories.forEach(cat => counts[cat.id] = 0);

    filteredTasks.forEach(t => {
      if (counts[t.serviceCategoryId] !== undefined) {
        counts[t.serviceCategoryId] += t.quantity;
      }
    });

    return state.serviceCategories.map(cat => ({
      name: cat.name,
      value: counts[cat.id],
      color: cat.color
    })).filter(item => item.value > 0);
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    const result = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
    setAiInsight(result || "Não foi possível gerar insights no momento.");
    setLoadingAi(false);
  };

  const totalQuantity = filteredTasks.reduce((acc, t) => acc + t.quantity, 0);

  const rangeLabels: Record<TimeRange, string> = {
    daily: 'Hoje',
    weekly: 'Últimos 7 dias',
    fortnightly: 'Última Quinzena',
    monthly: 'Último Mês',
    quarterly: 'Último Trimestre',
    semiannual: 'Último Semestre',
    annual: 'Último Ano'
  };

  return (
    <div className="space-y-8">
      {/* Time Range Selector */}
      <div className="flex flex-col sm:flex-row items-center justify-between bg-white p-4 rounded-2xl shadow-sm border border-slate-200 gap-4">
        <div className="flex items-center gap-2">
          <div className="text-blue-600">
            <Icons.Calendar />
          </div>
          <span className="font-bold text-slate-700">Período de Análise</span>
        </div>
        <div className="flex flex-wrap gap-2">
          {(Object.keys(rangeLabels) as TimeRange[]).map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${
                timeRange === range 
                  ? 'bg-blue-600 text-white shadow-md shadow-blue-200' 
                  : 'bg-slate-50 text-slate-500 hover:bg-slate-100'
              }`}
            >
              {rangeLabels[range]}
            </button>
          ))}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Total Produzido no Período</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{totalQuantity}</p>
          <div className="mt-4 flex items-center text-emerald-600 text-sm font-medium">
            <div className="w-2 h-2 rounded-full bg-emerald-500 mr-2 animate-pulse"></div>
            <span>{rangeLabels[timeRange]}</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Média por Colaborador</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">
            {state.people.length > 0 ? (totalQuantity / state.people.length).toFixed(1) : 0}
          </p>
          <div className="mt-4 flex items-center text-blue-600 text-sm font-medium">
            <Icons.People />
            <span className="ml-2">Equipe ativa</span>
          </div>
        </div>
