              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis 
                dataKey="date" 
                tickFormatter={(val) => {
                  const d = val.split('-');
                  return `${d[2]}/${d[1]}`;
                }}
                stroke="#94a3b8"
                fontSize={11}
                minTickGap={30}
              />
              <YAxis stroke="#94a3b8" fontSize={11} />
              <Tooltip 
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' }}
              />
              <Legend iconType="circle" />
              <Area 
                type="monotone" 
                dataKey="total" 
                name="Produção Total" 
                stroke="#3b82f6" 
                strokeWidth={3} 
                fillOpacity={1} 
                fill="url(#colorTotal)" 
              />
              {state.serviceCategories.map((cat) => (
                <Line 
                  key={cat.id} 
                  type="monotone" 
                  dataKey={cat.name} 
                  stroke={cat.color} 
                  strokeWidth={2} 
                  dot={timeRange === 'daily' || timeRange === 'weekly'} 
                  activeDot={{ r: 6 }} 
                />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Individual Team Productivity */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Produção por Colaborador</h3>
            <Icons.People />
          </div>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={teamData} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={100} 
                  stroke="#64748b" 
                  fontSize={12}
                  tickLine={false}
                  axisLine={false}
                />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Bar dataKey="quantity" name="Total Realizado" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Category Distribution Pie Chart */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Mix de Serviços</h3>
            <Icons.Settings />
          </div>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={categoryData}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                >
                  {categoryData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" align="center" layout="horizontal" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* AI Insights Section */}
      <div className="bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 rounded-3xl p-8 text-white shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-10">
          <div className="w-32 h-32 bg-white rounded-full"></div>
        </div>

        <div className="flex flex-col md:flex-row items-center justify-between gap-8 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-3 mb-4">
              <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
                <Icons.Sparkles />
              </div>
              <h2 className="text-2xl font-bold">Diagnóstico de Equipe por IA</h2>
            </div>
            <p className="text-indigo-100 mb-8 max-w-lg">
              Receba uma análise automatizada focada na evolução e desempenho individual referente ao período <strong>{rangeLabels[timeRange]}</strong>.
            </p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights}
                className="bg-white text-indigo-600 px-8 py-4 rounded-2xl font-bold hover:scale-105 transition-all shadow-xl active:scale-95"
              >
                Gerar Análise Estratégica
              </button>
            )}
          </div>

          {loadingAi && (
            <div className="flex-1 flex flex-col items-center gap-4 py-8">
              <div className="animate-spin h-10 w-10 border-4 border-white border-t-transparent rounded-full"></div>
              <span className="font-bold tracking-widest text-sm uppercase">Cruzando dados de {rangeLabels[timeRange]}...</span>
            </div>
          )}

          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/10 backdrop-blur-xl rounded-2xl p-6 border border-white/20 shadow-inner max-h-96 overflow-y-auto custom-scrollbar">
              <div className="flex justify-between items-start mb-4 border-b border-white/10 pb-4">
                <span className="text-xs font-bold uppercase tracking-widest bg-pink-500 px-3 py-1 rounded-full shadow-sm">Relatório Ativo</span>
                <button 
                  onClick={() => setAiInsight(null)}
                  className="text-white/60 hover:text-white transition-colors"
                >
                  <Icons.Trash />
                </button>
              </div>
              <div className="text-sm leading-relaxed whitespace-pre-wrap font-medium text-white/95">
                {aiInsight}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

