import React, { useState, useMemo } from 'react';
import { Person, Task, ServiceCategory, UserRole } from '../types';
import { Icons } from '../constants';

interface DailyLogProps {
  tasks: Task[];
  people: Person[];
  categories: ServiceCategory[];
  onAddTask: (task: Task) => void;
  onRemoveTask: (id: string) => void;
  userRole: UserRole;
}

const DailyLog: React.FC<DailyLogProps> = ({ tasks, people, categories, onAddTask, onRemoveTask, userRole }) => {
  const [selectedPerson, setSelectedPerson] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState('');
  const [description, setDescription] = useState('');
  const [quantity, setQuantity] = useState<number>(1);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [filterDate, setFilterDate] = useState(new Date().toISOString().split('T')[0]);

  const filteredTasks = useMemo(() => {
    return tasks
      .filter(t => t.date === filterDate)
      .sort((a, b) => b.id.localeCompare(a.id));
  }, [tasks, filterDate]);

  const handleAddTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPerson || !selectedCategoryId || !description.trim()) return;

    onAddTask({
      id: Math.random().toString(36).substr(2, 9),
      personId: selectedPerson,
      serviceCategoryId: selectedCategoryId,
      description: description.trim(),
      date,
      quantity: quantity
    });

    setDescription('');
    setQuantity(1);
  };

  return (
    <div className="space-y-8">
      {/* Registration Form - Both roles can add */}
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <h3 className="text-lg font-bold text-slate-800 mb-6">Novo Registro de Serviço</h3>
        <form onSubmit={handleAddTask} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4 items-end">
          <div className="lg:col-span-1">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Data</label>
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div className="lg:col-span-1">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Colaborador</label>
            <select
              value={selectedPerson}
              onChange={(e) => setSelectedPerson(e.target.value)}
              className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-blue-500"
              required
            >
              <option value="">Selecione...</option>
              {people.map(p => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
          </div>
          <div className="lg:col-span-1">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Serviço</label>
            <select
              value={selectedCategoryId}
              onChange={(e) => setSelectedCategoryId(e.target.value)}
              className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-blue-500"
              required
            >
              <option value="">Selecione...</option>
              {categories.map(cat => (
                <option key={cat.id} value={cat.id}>{cat.name}</option>
              ))}
            </select>
          </div>
          <div className="lg:col-span-2">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Descrição</label>
            <input
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="O que foi realizado?"
              className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-blue-500"
              required
            />
          </div>
          <div className="lg:col-span-1 flex gap-2">
            <div className="flex-1">
              <label className="block text-xs font-bold uppercase tracking-wider text-slate-500 mb-1">Quantidade</label>
              <input
                type="number"
                min="1"
                step="1"
                value={quantity}
                onChange={(e) => setQuantity(parseFloat(e.target.value))}
                className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <button
              type="submit"
              className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 transition-colors shadow-md mt-auto"
            >
              <Icons.Plus />
            </button>
          </div>
        </form>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-4">
            <h3 className="text-lg font-bold text-slate-800">Registros do Dia</h3>
            <span className="bg-blue-50 text-blue-700 px-3 py-1 rounded-full text-xs font-bold">
              {filteredTasks.length} Registros
            </span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-sm text-slate-500 font-medium">Visualizar data:</span>
            <input
              type="date"
              value={filterDate}
              onChange={(e) => setFilterDate(e.target.value)}
              className="px-4 py-1.5 rounded-lg border border-slate-200 outline-none text-sm font-medium"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-500 text-xs font-bold uppercase tracking-wider">
              <tr>
                <th className="px-6 py-4">Colaborador</th>
                <th className="px-6 py-4">Tipo de Serviço</th>
                <th className="px-6 py-4">Descrição</th>
                <th className="px-6 py-4 text-center">Quantidade</th>
                <th className="px-6 py-4 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredTasks.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-slate-400">
                    Nenhum registro encontrado para este dia.
                  </td>
                </tr>
              ) : (
                filteredTasks.map((task) => {
                  const person = people.find(p => p.id === task.personId);
                  const category = categories.find(c => c.id === task.serviceCategoryId);
                  return (
                    <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-xs font-bold text-slate-600">
                            {person?.name.charAt(0) || '?'}
                          </div>
                          <div>
                            <p className="font-semibold text-slate-800 text-sm">{person?.name || 'Removido'}</p>
                            <p className="text-xs text-slate-500">{person?.role || '-'}</p>
                          </div>
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span 
                          className="px-2.5 py-1 rounded-full text-[10px] font-bold text-white shadow-sm"
                          style={{ backgroundColor: category?.color || '#94a3b8' }}
                        >
                          {category?.name || 'Desconhecido'}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <p className="text-sm text-slate-700 line-clamp-1">{task.description}</p>
                      </td>
                      <td className="px-6 py-4 text-center font-bold text-slate-700 text-sm">
                        {task.quantity}
                      </td>
                      <td className="px-6 py-4 text-right">
                        {userRole === 'master' ? (
                          <button
                            onClick={() => onRemoveTask(task.id)}
                            className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                          >
                            <Icons.Trash />
                          </button>
                        ) : (
                          <span className="text-[10px] text-slate-300 italic">Somente Leitura</span>
                        )}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default DailyLog;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line, AreaChart, Area
} from 'recharts';
import { AppState, Task } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

type TimeRange = 'daily' | 'weekly' | 'fortnightly' | 'monthly' | 'quarterly' | 'semiannual' | 'annual';

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const [timeRange, setTimeRange] = useState<TimeRange>('weekly');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Filter tasks based on selected range
  const filteredTasks = useMemo(() => {
    const now = new Date();
    const rangeInDays: Record<TimeRange, number> = {
      daily: 1,
      weekly: 7,
      fortnightly: 15,
      monthly: 30,
      quarterly: 90,
      semiannual: 180,
      annual: 365
    };

    const thresholdDate = new Date();
    thresholdDate.setDate(now.getDate() - rangeInDays[timeRange]);
    const thresholdStr = thresholdDate.toISOString().split('T')[0];

    return state.tasks.filter(t => t.date >= thresholdStr);
  }, [state.tasks, timeRange]);

  // Data for Evolution Line Chart
  const evolutionData = useMemo(() => {
    const dates: Record<string, any> = {};
    const daysToGenerate: Record<TimeRange, number> = {
      daily: 1, weekly: 7, fortnightly: 15, monthly: 30, quarterly: 90, semiannual: 180, annual: 365
    };

    const count = daysToGenerate[timeRange];
    for (let i = 0; i < count; i++) {
      const d = new Date();
      d.setDate(d.getDate() - (count - 1 - i));
      const dateStr = d.toISOString().split('T')[0];
      dates[dateStr] = { date: dateStr, total: 0 };
      state.serviceCategories.forEach(cat => {
        dates[dateStr][cat.name] = 0;
      });
    }

    filteredTasks.forEach(t => {
      if (dates[t.date]) {
        const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
        if (cat) {
          dates[t.date][cat.name] += t.quantity;
          dates[t.date].total += t.quantity;
        }
      }
    });

    return Object.values(dates);
  }, [filteredTasks, state.serviceCategories, timeRange]);

  // Data for Individual Productivity (Bar Chart)
  const teamData = useMemo(() => {
    const data = state.people.map(person => {
      const total = filteredTasks
        .filter(t => t.personId === person.id)
        .reduce((sum, t) => sum + t.quantity, 0);
      return {
        name: person.name,
        quantity: total
      };
    });
    return data.sort((a, b) => b.quantity - a.quantity);
  }, [filteredTasks, state.people]);

  // Data for Category Distribution (Pie Chart)
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.serviceCategories.forEach(cat => counts[cat.id] = 0);

    filteredTasks.forEach(t => {
      if (counts[t.serviceCategoryId] !== undefined) {
        counts[t.serviceCategoryId] += t.quantity;
      }
    });

    return state.serviceCategories.map(cat => ({
      name: cat.name,
      value: counts[cat.id],
      color: cat.color
    })).filter(item => item.value > 0);
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    const result = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
    setAiInsight(result || "Não foi possível gerar insights no momento.");
    setLoadingAi(false);
  };

  const totalQuantity = filteredTasks.reduce((acc, t) => acc + t.quantity, 0);

  const rangeLabels: Record<TimeRange, string> = {
    daily: 'Hoje',
    weekly: 'Últimos 7 dias',
    fortnightly: 'Última Quinzena',
    monthly: 'Último Mês',
    quarterly: 'Último Trimestre',
    semiannual: 'Último Semestre',
    annual: 'Último Ano'
  };

  return (
    <div className="space-y-8">
      {/* Time Range Selector */}
      <div className="flex flex-col sm:flex-row items-center justify-between bg-white p-4 rounded-2xl shadow-sm border border-slate-200 gap-4">
        <div className="flex items-center gap-2">
          <div className="text-blue-600">
            <Icons.Calendar />
          </div>
          <span className="font-bold text-slate-700">Período de Análise</span>
        </div>
        <div className="flex flex-wrap gap-2">
          {(Object.keys(rangeLabels) as TimeRange[]).map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${
                timeRange === range 
                  ? 'bg-blue-600 text-white shadow-md shadow-blue-200' 
                  : 'bg-slate-50 text-slate-500 hover:bg-slate-100'
              }`}
            >
              {rangeLabels[range]}
            </button>
          ))}
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Total Produzido no Período</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">{totalQuantity}</p>
          <div className="mt-4 flex items-center text-emerald-600 text-sm font-medium">
            <div className="w-2 h-2 rounded-full bg-emerald-500 mr-2 animate-pulse"></div>
            <span>{rangeLabels[timeRange]}</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Colaboradores Ativos</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">
            {state.people.length}
          </p>
          <div className="mt-4 flex items-center text-blue-600 text-sm font-medium">
            <Icons.People />
            <span className="ml-2">Equipe cadastrada</span>
          </div>
        </div>
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-medium">Frequência de Registro</p>
          <p className="text-4xl font-bold text-slate-900 mt-2">
            {filteredTasks.length}
          </p>
          <div className="mt-4 flex items-center text-violet-600 text-sm font-medium">
            <Icons.Task />
            <span className="ml-2">Lançamentos</span>
          </div>
        </div>
      </div>

      {/* Evolution Progression Chart */}
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-8">
          <h3 className="text-lg font-bold text-slate-800">Progresso da Produção</h3>
          <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Evolução Temporal</span>
        </div>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={evolutionData}>
              <defs>
                <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                  <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis 
                dataKey="date" 
                tickFormatter={(val) => {
                  const d = val.split('-');
                  return `${d[2]}/${d[1]}`;
                }}
                stroke="#94a3b8"
                fontSize={11}
                minTickGap={30}
              />
              <YAxis stroke="#94a3b8" fontSize={11} />
              <Tooltip 
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' }}
              />
              <Legend iconType="circle" />
              <Area 
                type="monotone" 
                dataKey="total" 
                name="Produção Total" 
                stroke="#3b82f6" 
                strokeWidth={3} 
                fillOpacity={1} 
                fill="url(#colorTotal)" 
              />
              {state.serviceCategories.map((cat) => (
                <Line 
                  key={cat.id} 
                  type="monotone" 
                  dataKey={cat.name} 
                  stroke={cat.color} 
                  strokeWidth={2} 
                  dot={timeRange === 'daily' || timeRange === 'weekly'} 
                  activeDot={{ r: 6 }} 
                />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Individual Team Productivity */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Produção por Colaborador</h3>
            <Icons.People />
          </div>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={teamData} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={100} 
                  stroke="#64748b" 
                  fontSize={12}
                  tickLine={false}
                  axisLine={false}
                />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Bar dataKey="quantity" name="Total Realizado" fill="#3b82f6" radius={[0, 4, 4, 0]} barSize={20} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Category Distribution Pie Chart */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-slate-800">Mix de Serviços</h3>
            <Icons.Settings />
          </div>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={categoryData}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                >
                  {categoryData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" align="center" layout="horizontal" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* AI Insights Section */}
      <div className="bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 rounded-3xl p-8 text-white shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-8 opacity-10">
          <div className="w-32 h-32 bg-white rounded-full"></div>
        </div>

        <div className="flex flex-col md:flex-row items-center justify-between gap-8 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-3 mb-4">
              <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
                <Icons.Sparkles />
              </div>
              <h2 className="text-2xl font-bold">Diagnóstico de Equipe por IA</h2>
            </div>
            <p className="text-indigo-100 mb-8 max-w-lg">
              Receba uma análise automatizada focada na evolução e desempenho individual referente ao período <strong>{rangeLabels[timeRange]}</strong>.
            </p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights}
                className="bg-white text-indigo-600 px-8 py-4 rounded-2xl font-bold hover:scale-105 transition-all shadow-xl active:scale-95"
              >
                Gerar Análise Estratégica
              </button>
            )}
          </div>

          {loadingAi && (
            <div className="flex-1 flex flex-col items-center gap-4 py-8">
              <div className="animate-spin h-10 w-10 border-4 border-white border-t-transparent rounded-full"></div>
              <span className="font-bold tracking-widest text-sm uppercase">Cruzando dados de {rangeLabels[timeRange]}...</span>
            </div>
          )}

          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/10 backdrop-blur-xl rounded-2xl p-6 border border-white/20 shadow-inner max-h-96 overflow-y-auto custom-scrollbar">
              <div className="flex justify-between items-start mb-4 border-b border-white/10 pb-4">
                <span className="text-xs font-bold uppercase tracking-widest bg-pink-500 px-3 py-1 rounded-full shadow-sm">Relatório Ativo</span>
                <button 
                  onClick={() => setAiInsight(null)}
                  className="text-white/60 hover:text-white transition-colors"
                >
                  <Icons.Trash />
                </button>
              </div>
              <div className="text-sm leading-relaxed whitespace-pre-wrap font-medium text-white/95">
                {aiInsight}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { UserRole } from '../types';
import { Icons } from '../constants';

interface LoginProps {
  onLogin: (role: UserRole) => void;
}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    // Credenciais Master
    if (username.toUpperCase() === 'ANDERSON' && password === '1') {
      onLogin('master');
      return;
    }

    // Credenciais Básico
    if (username === '1' && password === '1') {
      onLogin('basic');
      return;
    }

    setError('Usuário ou senha inválidos.');
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="w-full max-w-md">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center p-4 bg-blue-600 rounded-3xl text-white shadow-xl shadow-blue-200 mb-6">
            <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
            </svg>
          </div>
          <h1 className="text-4xl font-extrabold text-slate-800 tracking-tight">Prod360</h1>
          <p className="text-slate-500 mt-2 font-medium">Gestão Inteligente de Produtividade</p>
        </div>

        <div className="bg-white p-8 rounded-[32px] shadow-2xl border border-slate-100 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-500 via-indigo-500 to-purple-500"></div>

          <h2 className="text-2xl font-bold text-slate-800 mb-6">Acesse sua conta</h2>

          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Usuário</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder="Digite seu usuário"
                className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all placeholder:text-slate-300 font-medium"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Senha</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="••••••••"
                className="w-full px-5 py-3.5 rounded-2xl border border-slate-200 focus:ring-4 focus:ring-blue-500/10 focus:border-blue-500 outline-none transition-all placeholder:text-slate-300 font-medium"
                required
              />
            </div>

            {error && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center gap-3 animate-shake">
                <div className="bg-red-500 text-white rounded-full p-1">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
                </div>
                <span className="text-sm font-bold text-red-600">{error}</span>
              </div>
            )}

            <button
              type="submit"
              className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold hover:bg-black transition-all shadow-xl shadow-slate-200 active:scale-95 flex items-center justify-center gap-2"
            >
              Entrar no Sistema
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-50">
            <div className="flex justify-between items-center text-xs text-slate-400 font-bold uppercase tracking-widest">
              <span>Nível Master</span>
              <span className="text-slate-300">|</span>
              <span>Nível Básico</span>
            </div>
          </div>
        </div>

        <p className="text-center text-slate-400 text-sm mt-8">
          © 2024 Prod360. Todos os direitos reservados.
        </p>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
import DailyLog from './components/DailyLog';
import ServiceManager from './components/ServiceManager';
import Login from './components/Login';
import { DEFAULT_CATEGORIES } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs' | 'services'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('prod360_data');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.serviceCategories) parsed.serviceCategories = DEFAULT_CATEGORIES;
      if (!parsed.userRole) parsed.userRole = 'master';
      return parsed;
    }
    return { 
      people: [], 
      tasks: [], 
      serviceCategories: DEFAULT_CATEGORIES,
      userRole: 'master' 
    };
  });

  useEffect(() => {
    localStorage.setItem('prod360_data', JSON.stringify(state));
  }, [state]);

  const handleLogin = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  const setUserRole = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    if (role === 'basic' && (activeTab === 'people' || activeTab === 'services')) {
      setActiveTab('dashboard');
    }
  };

  const addPerson = (person: Person) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({ ...prev, people: [...prev.people, person] }));
  };

  const removePerson = (id: string) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({
      ...prev,
      people: prev.people.filter(p => p.id !== id),
      tasks: prev.tasks.filter(t => t.personId !== id)
    }));
  };

  const addTask = (task: Task) => {
    setState(prev => ({ ...prev, tasks: [...prev.tasks, task] }));
  };

  const removeTask = (id: string) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.filter(t => t.id !== id)
    }));
  };

  const addServiceCategory = (cat: ServiceCategory) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({ ...prev, serviceCategories: [...prev.serviceCategories, cat] }));
  };

  const removeServiceCategory = (id: string) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({
      ...prev,
      serviceCategories: prev.serviceCategories.filter(c => c.id !== id),
      tasks: prev.tasks.filter(t => t.serviceCategoryId !== id)
    }));
  };

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userRole={state.userRole}
        onRoleChange={setUserRole}
        onLogout={handleLogout}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold text-slate-800">
              {activeTab === 'dashboard' && 'Visão Geral'}
              {activeTab === 'people' && 'Gerenciar Equipe'}
              {activeTab === 'logs' && 'Registro Diário'}
              {activeTab === 'services' && 'Tipos de Serviço'}
            </h1>
            <p className="text-slate-500 mt-2 font-medium">
              {activeTab === 'dashboard' && 'Monitore a produtividade e o desempenho da equipe.'}
              {activeTab === 'people' && 'Adicione ou remova membros da sua equipe.'}
              {activeTab === 'logs' && 'Visualize e gerencie os serviços realizados diariamente.'}
              {activeTab === 'services' && 'Personalize as categorias de serviço monitoradas.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
             <div className={`px-4 py-2 rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-sm ${
              state.userRole === 'master' ? 'bg-indigo-600 text-white' : 'bg-emerald-600 text-white'
            }`}>
              {state.userRole === 'master' ? 'Acesso Master' : 'Acesso Básico'}
            </div>
            <button 
              onClick={handleLogout}
              className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              title="Sair do sistema"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            </button>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <Dashboard state={state} />
        )}

        {activeTab === 'people' && state.userRole === 'master' && (
          <PeopleManager people={state.people} onAdd={addPerson} onRemove={removePerson} />
        )}

        {activeTab === 'logs' && (
          <DailyLog 
            tasks={state.tasks} 
            people={state.people} 
            categories={state.serviceCategories}
            onAddTask={addTask} 
            onRemoveTask={removeTask}
            userRole={state.userRole}
          />
        )}

        {activeTab === 'services' && state.userRole === 'master' && (
          <ServiceManager 
            categories={state.serviceCategories} 
            onAdd={addServiceCategory} 
            onRemove={removeServiceCategory} 
          />
        )}

        {(activeTab === 'people' || activeTab === 'services') && state.userRole === 'basic' && (
          <div className="bg-white p-12 rounded-3xl shadow-sm border border-slate-200 text-center">
            <div className="bg-slate-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-300">
              <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Acesso Restrito</h2>
            <p className="text-slate-500 max-w-sm mx-auto">Você está utilizando um perfil operacional (Básico) e não possui permissões para configurações de equipe ou serviços.</p>
            <button 
              onClick={() => setActiveTab('dashboard')}
              className="mt-8 bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold hover:bg-black transition-all shadow-xl shadow-slate-200"
            >
              Retornar ao Painel
            </button>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { Icons } from '../constants';
import { UserRole } from '../types';

interface SidebarProps {
  activeTab: 'dashboard' | 'people' | 'logs' | 'services';
  setActiveTab: (tab: 'dashboard' | 'people' | 'logs' | 'services') => void;
  userRole: UserRole;
  onRoleChange: (role: UserRole) => void;
  onLogout: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, userRole, onRoleChange, onLogout }) => {
  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <Icons.Dashboard />, restricted: false },
    { id: 'people', label: 'Equipe', icon: <Icons.People />, restricted: true },
    { id: 'logs', label: 'Registros', icon: <Icons.Calendar />, restricted: false },
    { id: 'services', label: 'Serviços', icon: <Icons.Settings />, restricted: true },
  ] as const;

  return (
    <aside className="w-72 bg-white border-r border-slate-200 flex flex-col hidden md:flex">
      <div className="p-8 border-b border-slate-100">
        <div className="flex items-center gap-3">
          <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-2.5 rounded-2xl text-white shadow-lg shadow-blue-100">
            <Icons.Task />
          </div>
          <span className="font-extrabold text-2xl tracking-tight text-slate-800">Prod360</span>
        </div>
      </div>

      <nav className="flex-1 p-6 space-y-2">
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 ml-4">Menu Principal</p>
        {menuItems.map((item) => {
          if (userRole === 'basic' && item.restricted) return null;

          const isActive = activeTab === item.id;
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all duration-300 ${
                isActive 
                  ? 'bg-blue-600 text-white font-bold shadow-xl shadow-blue-100 translate-x-1' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900 font-medium'
              }`}
            >
              <div className={isActive ? 'text-white' : 'text-slate-400'}>
                {item.icon}
              </div>
              {item.label}
            </button>
          );
        })}
      </nav>

      <div className="p-6 space-y-4">
        <div className="bg-slate-50 rounded-[24px] p-5 border border-slate-100">
          <div className="flex items-center gap-3 mb-4">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white font-bold ${
              userRole === 'master' ? 'bg-indigo-600' : 'bg-emerald-600'
            }`}>
              {userRole === 'master' ? 'A' : '1'}
            </div>
            <div>
              <p className="text-sm font-bold text-slate-800">{userRole === 'master' ? 'Anderson' : 'Usuário 1'}</p>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{userRole === 'master' ? 'Master' : 'Básico'}</p>
            </div>
          </div>

          <button 
            onClick={onLogout}
            className="w-full flex items-center justify-center gap-2 py-3 rounded-xl bg-white border border-slate-200 text-slate-600 text-xs font-bold hover:bg-red-50 hover:text-red-600 hover:border-red-100 transition-all shadow-sm"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            Sair do Sistema
          </button>
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line, AreaChart, Area
} from 'recharts';
import { AppState, Task } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

type TimeRange = 'daily' | 'weekly' | 'fortnightly' | 'monthly' | 'quarterly' | 'semiannual' | 'annual';

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const [timeRange, setTimeRange] = useState<TimeRange | 'custom'>('weekly');
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Filter tasks based on selected range OR specific date
  const filteredTasks = useMemo(() => {
    if (timeRange === 'custom' && selectedDate) {
      return state.tasks.filter(t => t.date === selectedDate);
    }

    const now = new Date();
    const rangeInDays: Record<string, number> = {
      daily: 1,
      weekly: 7,
      fortnightly: 15,
      monthly: 30,
      quarterly: 90,
      semiannual: 180,
      annual: 365
    };

    const days = rangeInDays[timeRange as string] || 7;
    const thresholdDate = new Date();
    thresholdDate.setDate(now.getDate() - days);
    const thresholdStr = thresholdDate.toISOString().split('T')[0];

    return state.tasks.filter(t => t.date >= thresholdStr);
  }, [state.tasks, timeRange, selectedDate]);

  // Data for Evolution Line Chart
  const evolutionData = useMemo(() => {
    const dates: Record<string, any> = {};

    if (timeRange === 'custom' && selectedDate) {
      // For a single day, we show that day and maybe one day before/after for context
      // But user specifically wants to see metrics of THAT day. 
      // To make the chart useful, we'll show a 3-day window around the selected date
      const centerDate = new Date(selectedDate + 'T00:00:00');
      for (let i = -2; i <= 0; i++) {
        const d = new Date(centerDate);
        d.setDate(d.getDate() + i);
        const dateStr = d.toISOString().split('T')[0];
        dates[dateStr] = { date: dateStr, total: 0 };
        state.serviceCategories.forEach(cat => {
          dates[dateStr][cat.name] = 0;
        });
      }
    } else {
      const daysToGenerate: Record<string, number> = {
        daily: 1, weekly: 7, fortnightly: 15, monthly: 30, quarterly: 90, semiannual: 180, annual: 365
      };
      const count = daysToGenerate[timeRange as string] || 7;
      for (let i = 0; i < count; i++) {
        const d = new Date();
        d.setDate(d.getDate() - (count - 1 - i));
        const dateStr = d.toISOString().split('T')[0];
        dates[dateStr] = { date: dateStr, total: 0 };
        state.serviceCategories.forEach(cat => {
          dates[dateStr][cat.name] = 0;
        });
      }
    }

    // Fill data
    state.tasks.forEach(t => {
      if (dates[t.date]) {
        const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
        if (cat) {
          dates[t.date][cat.name] += t.quantity;
          dates[t.date].total += t.quantity;
        }
      }
    });

    return Object.values(dates).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [state.tasks, state.serviceCategories, timeRange, selectedDate]);

  // Data for Individual Productivity (Bar Chart)
  const teamData = useMemo(() => {
    const data = state.people.map(person => {
      const total = filteredTasks
        .filter(t => t.personId === person.id)
        .reduce((sum, t) => sum + t.quantity, 0);
      return {
        name: person.name,
        quantity: total
      };
    });
    return data.sort((a, b) => b.quantity - a.quantity);
  }, [filteredTasks, state.people]);

  // Data for Category Distribution (Pie Chart)
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.serviceCategories.forEach(cat => counts[cat.id] = 0);

    filteredTasks.forEach(t => {
      if (counts[t.serviceCategoryId] !== undefined) {
        counts[t.serviceCategoryId] += t.quantity;
      }
    });

    return state.serviceCategories.map(cat => ({
      name: cat.name,
      value: counts[cat.id],
      color: cat.color
    })).filter(item => item.value > 0);
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    const result = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
    setAiInsight(result || "Não foi possível gerar insights no momento.");
    setLoadingAi(false);
  };

  const totalQuantity = filteredTasks.reduce((acc, t) => acc + t.quantity, 0);

  const rangeLabels: Record<string, string> = {
    daily: 'Hoje',
    weekly: 'Últimos 7 dias',
    fortnightly: 'Última Quinzena',
    monthly: 'Último Mês',
    quarterly: 'Último Trimestre',
    semiannual: 'Último Semestre',
    annual: 'Último Ano'
  };

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const date = e.target.value;
    setSelectedDate(date);
    if (date) {
      setTimeRange('custom');
    } else {
      setTimeRange('weekly');
    }
  };

  const displayPeriodLabel = timeRange === 'custom' && selectedDate 
    ? `Dia: ${selectedDate.split('-').reverse().join('/')}` 
    : rangeLabels[timeRange as string];

  return (
    <div className="space-y-8">
      {/* Time Range Selector & Specific Date Picker */}
      <div className="flex flex-col xl:flex-row items-stretch xl:items-center justify-between bg-white p-6 rounded-3xl shadow-sm border border-slate-200 gap-6">
        <div className="flex flex-col md:flex-row items-start md:items-center gap-6">
          <div className="flex items-center gap-3">
            <div className="bg-blue-50 p-2 rounded-xl text-blue-600">
              <Icons.Calendar />
            </div>
            <span className="font-bold text-slate-800 whitespace-nowrap">Período de Análise</span>
          </div>

          <div className="flex flex-wrap gap-2">
            {(Object.keys(rangeLabels) as TimeRange[]).map((range) => (
              <button
                key={range}
                onClick={() => {
                  setTimeRange(range);
                  setSelectedDate('');
                }}
                className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${
                  timeRange === range 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
                    : 'bg-slate-50 text-slate-500 hover:bg-slate-100'
                }`}
              >
                {rangeLabels[range]}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-3 border-t xl:border-t-0 xl:border-l border-slate-100 pt-6 xl:pt-0 xl:pl-6">
          <label className="text-xs font-bold text-slate-400 uppercase tracking-widest whitespace-nowrap">Ou Data Específica:</label>
          <div className="relative">
            <input
              type="date"
              value={selectedDate}
              onChange={handleDateChange}
              className={`px-4 py-2 rounded-xl text-xs font-bold border outline-none transition-all ${
                timeRange === 'custom' 
                  ? 'border-blue-500 ring-4 ring-blue-500/10 bg-blue-50 text-blue-700' 
                  : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'
              }`}
            />
            {selectedDate && (
              <button 
                onClick={() => {setSelectedDate(''); setTimeRange('weekly');}}
                className="absolute -right-2 -top-2 bg-slate-800 text-white p-1 rounded-full hover:bg-red-500 transition-colors shadow-md"
              >
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 transition-hover hover:shadow-md">
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider">Total Produzido</p>
          <div className="flex items-baseline gap-2 mt-2">
            <p className="text-5xl font-black text-slate-900">{totalQuantity}</p>
            <span className="text-slate-400 font-bold text-sm">itens</span>
          </div>
          <div className="mt-6 flex items-center text-emerald-600 text-xs font-bold bg-emerald-50 px-3 py-1.5 rounded-full w-fit">
            <div className="w-2 h-2 rounded-full bg-emerald-500 mr-2"></div>
            <span>{displayPeriodLabel}</span>
          </div>
        </div>
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 transition-hover hover:shadow-md">
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider">Colaboradores</p>
          <div className="flex items-baseline gap-2 mt-2">
            <p className="text-5xl font-black text-slate-900">{state.people.length}</p>
            <span className="text-slate-400 font-bold text-sm">ativos</span>
          </div>
          <div className="mt-6 flex items-center text-blue-600 text-xs font-bold bg-blue-50 px-3 py-1.5 rounded-full w-fit">
            <Icons.People />
            <span className="ml-2">Equipe Total</span>
          </div>
        </div>
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 transition-hover hover:shadow-md">
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider">Registros</p>
          <div className="flex items-baseline gap-2 mt-2">
            <p className="text-5xl font-black text-slate-900">{filteredTasks.length}</p>
            <span className="text-slate-400 font-bold text-sm">lançamentos</span>
          </div>
          <div className="mt-6 flex items-center text-violet-600 text-xs font-bold bg-violet-50 px-3 py-1.5 rounded-full w-fit">
            <Icons.Task />
            <span className="ml-2">Atividade do Período</span>
          </div>
        </div>
      </div>

      {/* Evolution Progression Chart */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
        <div className="flex items-center justify-between mb-10">
          <div>
            <h3 className="text-xl font-extrabold text-slate-800">Gráfico de Evolução</h3>
            <p className="text-slate-400 text-sm font-medium mt-1">Comparativo de produtividade por categoria</p>
          </div>
          <div className="bg-slate-50 px-4 py-2 rounded-2xl text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
            {displayPeriodLabel}
          </div>
        </div>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={evolutionData}>
              <defs>
                <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                  <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis 
                dataKey="date" 
                tickFormatter={(val) => {
                  const d = val.split('-');
                  return `${d[2]}/${d[1]}`;
                }}
                stroke="#94a3b8"
                fontSize={11}
                fontWeight={600}
                minTickGap={30}
              />
              <YAxis stroke="#94a3b8" fontSize={11} fontWeight={600} />
              <Tooltip 
                contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 25px 50px -12px rgba(0,0,0,0.1)', padding: '16px' }}
                itemStyle={{ fontWeight: 700, fontSize: '12px' }}
                labelStyle={{ fontWeight: 800, color: '#1e293b', marginBottom: '8px' }}
              />
              <Legend iconType="circle" wrapperStyle={{ paddingTop: '20px', fontWeight: 600, fontSize: '12px' }} />
              <Area 
                type="monotone" 
                dataKey="total" 
                name="Produção Total" 
                stroke="#3b82f6" 
                strokeWidth={4} 
                fillOpacity={1} 
                fill="url(#colorTotal)" 
              />
              {state.serviceCategories.map((cat) => (
                <Line 
                  key={cat.id} 
                  type="monotone" 
                  dataKey={cat.name} 
                  stroke={cat.color} 
                  strokeWidth={2} 
                  dot={{ r: 4, strokeWidth: 2, fill: '#fff' }} 
                  activeDot={{ r: 6, strokeWidth: 0 }} 
                />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Individual Team Productivity */}
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-extrabold text-slate-800">Ranking da Equipe</h3>
            <div className="text-slate-300">
              <Icons.People />
            </div>
          </div>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={teamData} layout="vertical" margin={{ left: 20 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis 
                  dataKey="name" 
                  type="category" 
                  width={100} 
                  stroke="#64748b" 
                  fontSize={12}
                  fontWeight={700}
                  tickLine={false}
                  axisLine={false}
                />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Bar dataKey="quantity" name="Total Realizado" fill="#3b82f6" radius={[0, 8, 8, 0]} barSize={24} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Category Distribution Pie Chart */}
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-extrabold text-slate-800">Distribuição de Serviços</h3>
            <div className="text-slate-300">
              <Icons.Settings />
            </div>
          </div>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={categoryData}
                  cx="50%"
                  cy="50%"
                  innerRadius={70}
                  outerRadius={100}
                  paddingAngle={8}
                  dataKey="value"
                  stroke="none"
                >
                  {categoryData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                />
                <Legend verticalAlign="bottom" align="center" layout="horizontal" wrapperStyle={{ paddingTop: '20px', fontWeight: 600, fontSize: '11px' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* AI Insights Section */}
      <div className="bg-gradient-to-br from-indigo-700 via-blue-700 to-indigo-900 rounded-[40px] p-10 text-white shadow-2xl relative overflow-hidden group">
        <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-white/10 rounded-full blur-3xl group-hover:scale-110 transition-transform duration-700"></div>
        <div className="absolute -top-24 -left-24 w-64 h-64 bg-blue-400/10 rounded-full blur-3xl"></div>

        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-6">
              <div className="bg-white/10 p-3 rounded-2xl backdrop-blur-md border border-white/20">
                <Icons.Sparkles />
              </div>
              <h2 className="text-3xl font-black tracking-tight">Análise Inteligente</h2>
            </div>
            <p className="text-blue-100 text-lg mb-10 max-w-lg leading-relaxed font-medium">
              A inteligência artificial irá analisar os volumes produzidos em <strong>{displayPeriodLabel}</strong> para fornecer recomendações estratégicas.
            </p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights}
                className="bg-white text-indigo-700 px-10 py-5 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl hover:-translate-y-1 active:translate-y-0"
              >
                Gerar Relatório de Desempenho
              </button>
            )}
          </div>

          {loadingAi && (
            <div className="flex-1 flex flex-col items-center gap-6 py-12">
              <div className="relative">
                <div className="animate-spin h-16 w-16 border-4 border-white/20 border-t-white rounded-full"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
                </div>
              </div>
              <span className="font-black tracking-[0.3em] text-[10px] uppercase text-white/70">Processando métricas...</span>
            </div>
          )}

          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[32px] p-8 border border-white/10 shadow-inner max-h-[400px] overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-right-10 duration-500">
              <div className="flex justify-between items-start mb-6 border-b border-white/10 pb-6">
                <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase tracking-widest text-blue-300">Diagnóstico Concluído</span>
                  <span className="text-sm font-bold mt-1">Período: {displayPeriodLabel}</span>
                </div>
                <button 
                  onClick={() => setAiInsight(null)}
                  className="bg-white/10 p-2 rounded-xl text-white/40 hover:text-white hover:bg-white/20 transition-all"
                >
                  <Icons.Trash />
                </button>
              </div>
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium text-white/90">
                {aiInsight}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

